const cfg = $input.first().json;
const d = new Date();
const fim = d.toISOString().slice(0, 10);
const ini = new Date(d.getTime() - Number(cfg.dias_atras ?? 7) * 86400000).toISOString().slice(0, 10);
const urls = [
  { label: 'sem_filtro', url: `${cfg.bling_base_url}/nfe?pagina=1&limite=5` },
  { label: 'com_datas', url: `${cfg.bling_base_url}/nfe?pagina=1&limite=5&dataEmissaoInicial=${encodeURIComponent(ini + ' 00:00:00')}&dataEmissaoFinal=${encodeURIComponent(fim + ' 23:59:59')}` },
  { label: 'com_tipo_saida', url: `${cfg.bling_base_url}/nfe?pagina=1&limite=5&tipo=1&dataEmissaoInicial=${encodeURIComponent(ini + ' 00:00:00')}&dataEmissaoFinal=${encodeURIComponent(fim + ' 23:59:59')}` },
];
return urls.map((u) => ({ json: { ...cfg, ...u, dataInicial: ini, dataFinal: fim } }));

const inputs = $('URLs teste').all();
const outputs = $input.all();
const linhas = [];

for (let i = 0; i < outputs.length; i++) {
  const label = inputs[i]?.json?.label ?? `req_${i}`;
  const item = outputs[i].json;
  if (item.error) {
    const e = item.error;
    linhas.push({
      teste: label,
      ok: false,
      erro: typeof e === 'string' ? e : (e.message ?? e.description ?? e.type ?? JSON.stringify(e)),
    });
    continue;
  }
  const batch = item.data ?? [];
  const n = Array.isArray(batch) ? batch.length : 0;
  const ex = n > 0 ? batch[0] : null;
  linhas.push({
    teste: label,
    ok: true,
    notas: n,
    exemplo_id: ex?.id ?? null,
    exemplo_serie: ex?.serie ?? ex?.numeroSerie ?? null,
    exemplo_tipo: ex?.tipo ?? null,
    exemplo_data: ex?.dataEmissao ?? ex?.data ?? null,
    tem_itens: Array.isArray(ex?.itens) ? ex.itens.length : 0,
  });
}

const cfg = $('Config').first().json;
return [{ json: { periodo: `${$('URLs teste').first().json.dataInicial} a ${$('URLs teste').first().json.dataFinal}`, resultados: linhas } }];
